import { boolean, date, number, record, records, string } from './primitives.ts';
export function parseSize(name: string | null) {
  const match = /(\d*\.?\d+)\s*(g|gram|ml)\b/i.exec(name ?? '');
  return { g: match ? number(match[1]) : null, unit: match?.[2].toLowerCase() ?? null,
    volumeSize: match?.[2].toLowerCase() === 'ml' };
}
export function itemType(name: string | null) {
  return /disposable|all.in.one|\baio\b|device/i.test(name ?? '') ? 'disposable' :
    /\bpod\b/i.test(name ?? '') ? 'pod' : /cart/i.test(name ?? '') ? 'cart' : 'other';
}
export function normalizeSnapshot(input: unknown, requestedDate: string) {
  const raw = record(input), suppliedDate = date(raw.date);
  return {
    raw, date: suppliedDate ?? requestedDate, dateInferred: suppliedDate === null,
    stores: records(raw.stores).map((store, storeIndex) => {
      const listing = record(store.listing), slug = string(store.slug);
      return {
        raw: store, slug, id: slug ?? `unknown-store:${storeIndex}`,
        name: string(listing.name) ?? slug ?? 'Unknown store',
        recOnly: boolean(store.rec_only), announcement: string(listing.announcement),
        volumeDealItems: records(store.volume_deal_items),
        items: records(store.items).map((item, itemIndex) => {
          const name = string(item.name), brand = string(item.brand), size = parseSize(name);
          const rawThc = number(item.thc);
          const thc = !rawThc ? null : rawThc > 100 ?
            size.g !== null && size.g > 0 ? rawThc / (size.g * 10) : null : rawThc;
          const listed = number(item.listed), original = number(item.original);
          return {
            raw: item, rowId: JSON.stringify([suppliedDate ?? requestedDate, storeIndex, itemIndex]),
            inferredKey: slug && name ? JSON.stringify([slug, brand ?? '', name]) : null,
            storeId: slug ?? `unknown-store:${storeIndex}`, slug,
            storeName: string(listing.name) ?? slug ?? 'Unknown store', recOnly: boolean(store.rec_only),
            name: name ?? 'Unnamed item', brand, type: itemType(name), ...size,
            listed, original, base: original ?? listed, afterTax: number(item.after_tax),
            thc, rawThc, menuListed: boolean(item.in_stock_on_menu), deal: string(item.deal),
            discountPercent: original !== null && original > 0 && listed !== null && listed < original - .005
              ? 100 * (1 - listed / original) : null,
          };
        }),
      };
    }),
    halfValue: {
      raw: record(raw.half_value), available: raw.half_value !== null && typeof raw.half_value === 'object' && !Array.isArray(raw.half_value),
      pairs: records(record(raw.half_value).pairs), types: records(record(raw.half_value).types),
      pairCount: number(record(raw.half_value).pair_count),
    },
  };
}
export type Snapshot = ReturnType<typeof normalizeSnapshot>;
export type Item = Snapshot['stores'][number]['items'][number];
export function normalizeManual(input: unknown) {
  return records(Array.isArray(input) ? input : record(input).entries).map(raw => ({
    raw, date: string(raw.date), store: string(raw.store), name: string(raw.name),
    price: number(raw.price), afterTax: number(raw.after_tax), sizeG: number(raw.size_g),
    dealText: string(raw.deal_text), inStoreOnly: boolean(raw.in_store_only),
  }));
}
export function normalizeRegistry(input: unknown) {
  return Object.entries(record(input)).filter(([, value]) => value !== null && typeof value === 'object' && !Array.isArray(value))
    .map(([key, value]) => { const raw = record(value); return {
      raw, key, name: string(raw.name), firstSeen: string(raw.first_seen), lastSeen: string(raw.last_seen),
      daysSeen: Array.isArray(raw.days_seen) ? raw.days_seen.filter((v): v is string => typeof v === 'string') : [],
      lastListed: number(raw.last_listed),
    }; });
}
export function normalizeStatus(input: unknown) {
  const raw = record(input);
  return { raw, date: string(raw.date), ok: boolean(raw.ok), error: string(raw.error),
    alerts: records(raw.alerts).map(alert => ({ raw: alert, level: string(alert.level),
      rule: string(alert.rule), change: alert.change ?? null, slug: string(alert.slug),
      name: string(alert.name), listed: number(alert.listed), was: number(alert.was) })),
  };
}
export function normalizeCadence(input: unknown) {
  const raw = record(input);
  return { raw, date: string(raw.date), brands: Object.entries(record(raw.brands)).map(([key, value]) => {
    const entry = record(value), separator = key.indexOf('|'), prior = record(entry.prior);
    return { raw: entry, key, store: separator >= 0 ? key.slice(0, separator) : key,
      brand: separator >= 0 ? key.slice(separator + 1) : null,
      learned: boolean(entry.learned), daysSeen: number(entry.days_seen),
      gaps: Array.isArray(entry.gaps) ? entry.gaps : null,
      daysSinceSeen: number(entry.days_since_seen), medianGapDays: number(entry.median_gap_days),
      prior: { lo: number(prior.lo), hi: number(prior.hi) } };
  }) };
}
export function normalizeDeals(input: unknown) {
  const raw = record(input);
  return { raw, date: string(raw.date), deals: Object.entries(record(raw.stores)).flatMap(([store, values]) =>
    records(values).map(entry => ({ raw: entry, store, title: string(entry.title),
      recurring: boolean(entry.recurring), daysSeen: number(entry.days_seen), itemsLast: number(entry.items_last),
      weekdays: Array.from({ length: 7 }, (_, i) => number(Array.isArray(entry.weekdays) ? entry.weekdays[i] : null)),
    }))) };
}
