import { date, isRecord, record } from './primitives.ts';
import { normalizeCadence, normalizeDeals, normalizeManual, normalizeRegistry,
  normalizeSnapshot, normalizeStatus, type Snapshot } from './adapters.ts';
const base = '/dispensary/data/';
export const endpoints = {
  manifest: base + 'manifest.json', registry: base + 'registry.json', manual: base + 'manual.json',
  status: base + 'status.json', cadence: base + 'cadence.json', deals: base + 'deal_patterns.json',
} as const;
export type Source = { url: string; state: 'ready' | 'missing' | 'error';
  receivedAt: string; error: string | null; raw: unknown };
export type LoadOptions = { signal?: AbortSignal; timeoutMs?: number; fetcher?: typeof fetch };
async function read(url: string, valid: (v: unknown) => boolean, options: LoadOptions): Promise<Source> {
  const controller = new AbortController(), abort = () => controller.abort();
  if (options.signal?.aborted) throw new DOMException('Load cancelled', 'AbortError');
  options.signal?.addEventListener('abort', abort, { once: true });
  const timer = setTimeout(abort, options.timeoutMs ?? 15000);
  let state: Source['state'] = 'ready', error: string | null = null, raw: unknown = null;
  try {
    const response = await (options.fetcher ?? fetch)(url, { cache: 'no-store', signal: controller.signal });
    if (!response.ok) { state = response.status === 404 ? 'missing' : 'error'; throw new Error(`HTTP ${response.status}`); }
    raw = await response.json();
    if (!valid(raw)) throw new Error('Unexpected JSON shape');
  } catch (reason) {
    if (options.signal?.aborted) throw new DOMException('Load cancelled', 'AbortError');
    if (state === 'ready') state = 'error';
    error = controller.signal.aborted ? 'Request timed out' : reason instanceof Error ? reason.message : 'Request failed';
  } finally {
    clearTimeout(timer); options.signal?.removeEventListener('abort', abort);
  }
  return { url, state, receivedAt: new Date().toISOString(), error, raw };
}
export async function loadDispensary(options: LoadOptions = {}) {
  const names = Object.keys(endpoints) as (keyof typeof endpoints)[];
  const validators: Record<keyof typeof endpoints, (v: unknown) => boolean> = {
    manifest: v => isRecord(v) && Array.isArray(v.dates),
    manual: v => Array.isArray(v) || isRecord(v) && Array.isArray(v.entries),
    registry: isRecord, status: isRecord, cadence: isRecord, deals: isRecord,
  };
  const results = await Promise.all(names.map(name => read(endpoints[name], validators[name], options)));
  const sources = Object.fromEntries(names.map((name, i) => [name, results[i]])) as Record<keyof typeof endpoints, Source>;
  const manifest = sources.manifest.state === 'ready' ? record(sources.manifest.raw) : {};
  // Preserve the last-14 manifest window. Invalid path components never become URLs.
  const window = Array.isArray(manifest.dates) ? manifest.dates.slice(-14) : [];
  const dates = [...new Set(window.map(date).filter((v): v is string => v !== null))];
  const warnings = window.some(value => date(value) === null) ? ['Invalid manifest dates were skipped.'] : [];
  const snapshotSources: Source[] = new Array(dates.length);
  let next = 0;
  await Promise.all(Array.from({ length: Math.min(4, dates.length) }, async () => {
    while (next < dates.length) {
      const index = next++;
      snapshotSources[index] = await read(base + 'snapshots/' + dates[index] + '.json', isRecord, options);
    }
  }));
  if (options.signal?.aborted) throw new DOMException('Load cancelled', 'AbortError');
  const snapshots: Snapshot[] = snapshotSources.flatMap((source, i) => source.state === 'ready'
    ? [normalizeSnapshot(source.raw, dates[i])] : []).sort((a, b) => a.date.localeCompare(b.date));
  const value = (name: keyof typeof endpoints) => sources[name].state === 'ready' ? sources[name].raw : null;
  return { sources, snapshotSources, warnings, snapshots, latest: snapshots.at(-1) ?? null,
    registry: normalizeRegistry(value('registry')), manual: normalizeManual(value('manual')),
    status: normalizeStatus(value('status')), cadence: normalizeCadence(value('cadence')),
    deals: normalizeDeals(value('deals')), loadedAt: new Date().toISOString() };
}
export type DispensaryData = Awaited<ReturnType<typeof loadDispensary>>;
