import type { Item, Snapshot } from '../data/adapters.ts';
export type PriceComparison = {
  state: 'matched' | 'ambiguous' | 'unavailable'; previousDate: string | null;
  previousListed: number | null; drop: number | null;
};
function group(items: Item[]) {
  const map = new Map<string, Item[]>();
  for (const item of items) if (item.inferredKey) {
    const bucket = map.get(item.inferredKey) ?? [];
    bucket.push(item); map.set(item.inferredKey, bucket);
  }
  return map;
}
export function latestItemsWithHistory(snapshots: Snapshot[]) {
  const ordered = [...snapshots].sort((a, b) => a.date.localeCompare(b.date));
  const latest = ordered.at(-1);
  if (!latest) return [];
  const current = ordered.filter(s => s.date === latest.date).flatMap(s => s.stores.flatMap(st => st.items));
  const previousDate = ordered.map(s => s.date).filter(d => d < latest.date).at(-1) ?? null;
  const previous = group(ordered.filter(s => s.date === previousDate).flatMap(s => s.stores.flatMap(st => st.items)));
  const now = group(current);
  return current.map(item => {
    const key = item.inferredKey, matches = key ? previous.get(key) ?? [] : [];
    let comparison: PriceComparison = { state: 'unavailable', previousDate, previousListed: null, drop: null };
    if (key && ((now.get(key)?.length ?? 0) > 1 || matches.length > 1)) comparison.state = 'ambiguous';
    else if (matches.length === 1 && item.listed !== null && matches[0].listed !== null) {
      const was = matches[0].listed;
      comparison = { state: 'matched', previousDate, previousListed: was,
        drop: item.listed < was - .005 ? was - item.listed : null };
    }
    return { ...item, comparison };
  });
}
