import { readFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import ts from 'typescript';
function literal(node: ts.Expression): unknown {
  if (ts.isParenthesizedExpression(node)) return literal(node.expression);
  if (ts.isStringLiteral(node) || ts.isNoSubstitutionTemplateLiteral(node)) return node.text;
  if (ts.isNumericLiteral(node)) {
    const value = Number(node.text); if (Number.isFinite(value)) return value;
  }
  if (node.kind === ts.SyntaxKind.TrueKeyword) return true;
  if (node.kind === ts.SyntaxKind.FalseKeyword) return false;
  if (node.kind === ts.SyntaxKind.NullKeyword) return null;
  if (ts.isPrefixUnaryExpression(node) && ts.isNumericLiteral(node.operand) &&
      [ts.SyntaxKind.PlusToken, ts.SyntaxKind.MinusToken].includes(node.operator)) {
    const value = Number(node.operand.text) * (node.operator === ts.SyntaxKind.MinusToken ? -1 : 1);
    if (Number.isFinite(value)) return value;
  }
  if (ts.isArrayLiteralExpression(node)) return node.elements.map(element => literal(element));
  if (ts.isObjectLiteralExpression(node)) {
    const result: Record<string, unknown> = Object.create(null);
    for (const property of node.properties) {
      if (!ts.isPropertyAssignment(property) || !(ts.isIdentifier(property.name) ||
          ts.isStringLiteral(property.name) || ts.isNumericLiteral(property.name))) throw new Error('Parent data requires literal property assignments');
      const key = property.name.text;
      if (['__proto__', 'prototype', 'constructor'].includes(key) || Object.hasOwn(result, key))
        throw new Error('Unsafe or duplicate parent data key: ' + key);
      result[key] = literal(property.initializer);
    }
    return result;
  }
  throw new Error('Parent data must be a static literal; expressions are never executed');
}
export function parseLegacyParent(html: string) {
  const declarations: ts.Expression[] = [];
  for (const match of html.matchAll(/<script\b[^>]*>([\s\S]*?)<\/script\s*>/gi)) {
    const source = ts.createSourceFile('parent.js', match[1], ts.ScriptTarget.ESNext, true, ts.ScriptKind.JS);
    if ((source as ts.SourceFile & { parseDiagnostics: readonly ts.Diagnostic[] }).parseDiagnostics.length)
      throw new Error('Parent script contains invalid JavaScript syntax');
    for (const statement of source.statements) if (ts.isVariableStatement(statement))
      for (const declaration of statement.declarationList.declarations)
        if (ts.isIdentifier(declaration.name) && declaration.name.text === 'D') {
          if (!declaration.initializer) throw new Error('Parent D has no initializer');
          declarations.push(declaration.initializer);
        }
  }
  if (declarations.length !== 1) throw new Error('Expected exactly one top-level parent data literal D');
  const value = literal(declarations[0]);
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Parent D must be an object');
  return value as Record<string, unknown>;
}
export async function readLegacyParent() {
  // Read the owner-maintained source; never duplicate or rewrite its embedded data.
  return parseLegacyParent(await readFile(resolve(process.cwd(), '../parent/index.html'), 'utf8'));
}
