  return typeof value === 'object' ? JSON.stringify(value) : String(value);
}
export function rows(value: unknown): unknown[][] | null {
  return Array.isArray(value) ? value.map(row => Array.isArray(row) ? row : [row]) : null;
}
export function reference(value: unknown): string | null {
  if (typeof value !== 'string') return null;
  try { const url = new URL(value); return ['https:', 'http:'].includes(url.protocol) ? url.href : null; }
  catch { return null; }
}
export function summary(data: Record<string, unknown>) {
  const open = rows(data.open), asks = rows(data.asks), results = rows(data.results);
  return [
    { label: 'Waiting on you', value: open?.filter(row => row[0] === 'him' && row[2] === 'wait').length ?? null },
    { label: 'Assigned to agent', value: open?.filter(row => row[0] === 'me').length ?? null },
    { label: 'Asks running', value: asks?.filter(row => row[2] === 'run').length ?? null },
    { label: 'Results logged', value: results?.length ?? null },
