<script>
  const input = document.querySelector<HTMLInputElement>('#q');
  function filter() {
    const query = input?.value.trim().toLocaleLowerCase() ?? '';
    let shown = 0, total = 0;
    for (const section of document.querySelectorAll<HTMLElement>('.parent-section')) {
      let count = 0;
      for (const row of section.querySelectorAll<HTMLTableRowElement>('[data-parent-row]')) {
        row.hidden = !(row.dataset.search ?? '').includes(query);
        if (!row.hidden) count++;
        total++;
      }
      shown += count;
      const label = section.querySelector('[data-row-count]');
      if (label) label.textContent = `${count} matching records`;
      const empty = section.querySelector<HTMLElement>('[data-no-match]');
      if (empty) empty.hidden = count !== 0;
    }
    const status = document.querySelector('#parent-matches');
    if (status) status.textContent = `${shown} of ${total} snapshot records shown`;
  }
  input?.addEventListener('input', filter);
  document.querySelector('#parent-clear')?.addEventListener('click', () => {
    if (input) { input.value = ''; filter(); input.focus(); }
  });
</script>
