const themeQuery=matchMedia('(prefers-color-scheme: dark)');
function syncTheme(){const dark=document.documentElement.dataset.theme==='dark'||(!document.documentElement.dataset.theme&&themeQuery.matches);$('theme').textContent=dark?'Light mode':'Dark mode';$('theme').setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode')}
$('theme').onclick=()=>{document.documentElement.dataset.theme=$('theme').textContent==='Dark mode'?'dark':'light';try{localStorage.setItem('cockpit-theme',document.documentElement.dataset.theme)}catch{}syncTheme()};themeQuery.addEventListener('change',syncTheme);syncTheme();
