function rows(){const out=[];snaps.forEach(s=>arr(s.stores).forEach(st=>arr(st.items).forEach(i=>{const g=size(i.name),base=num(i.original)??num(i.listed),tv=num(i.thc),tp=!tv?null:tv>100?(g>0?tv/(g*10):null):tv;if(base==null)return;if(tp!=null&&tp<75&&!$('lowthc').checked)return;out.push({date:text(s.date),store:(text(st.listing?.name)||text(st.slug)||'Unknown store')+(st.rec_only?' (rec only)':''),slug:text(st.slug),name:text(i.name)||'Unnamed item',brand:text(i.brand),type:typ(i.name),g,base,listed:num(i.listed),at:num(i.after_tax),thc:tp,deal:text(i.deal),stock:i.in_stock_on_menu})})));return out}
