// Table text is always inserted with textContent; search/sort state survives rerenders.
const tables=new Map();
function table(id,title,heads,data){let t=tables.get(id);if(!t){const el=$(id),tools=document.createElement('div'),label=document.createElement('label'),input=document.createElement('input'),count=document.createElement('span'),wrap=document.createElement('div');tools.className='table-tools';label.textContent='Filter '+title;input.type='search';input.placeholder='Search these rows';input.id=id+'-search';label.htmlFor=input.id;label.append(input);count.className='table-count';count.setAttribute('aria-live','polite');tools.append(label,count);wrap.className='scroll';wrap.tabIndex=0;wrap.setAttribute('role','region');wrap.setAttribute('aria-label',title);el.before(tools,wrap);wrap.append(el);t={el,input,count,heads:[],data:[],sort:-1,dir:1,title};tables.set(id,t);input.oninput=()=>drawTable(t)}t.heads=heads;t.data=data;t.title=title;drawTable(t)}
function drawTable(t){const q=t.input.value.trim().toLowerCase(),data=t.data.filter(r=>r.some(v=>text(v).toLowerCase().includes(q))).map((r,i)=>({r,i}));if(t.sort>=0)data.sort((a,b)=>{const av=a.r[t.sort],bv=b.r[t.sort],an=numericCell(av),bn=numericCell(bv);if(!text(av)||av==='—')return !text(bv)||bv==='—'?a.i-b.i:1;if(!text(bv)||bv==='—')return -1;return ((an!=null&&bn!=null)?an-bn:text(av).localeCompare(text(bv),undefined,{numeric:true}))*t.dir||a.i-b.i});t.el.replaceChildren();const cap=document.createElement('caption');cap.textContent=t.title+' · Select a column to sort';const head=document.createElement('thead'),hr=document.createElement('tr');t.heads.forEach((h,i)=>{const th=document.createElement('th'),b=document.createElement('button');th.scope='col';th.setAttribute('aria-sort',t.sort===i?(t.dir===1?'ascending':'descending'):'none');b.type='button';b.textContent=h+(t.sort===i?(t.dir===1?' ↑':' ↓'):' ↕');b.onclick=()=>{t.dir=t.sort===i?-t.dir:1;t.sort=i;drawTable(t);t.el.querySelectorAll('th button')[i].focus()};th.append(b);hr.append(th)});head.append(hr);const body=document.createElement('tbody');if(!data.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=t.heads.length;td.className='empty';td.textContent=q?'No rows match this search. Clear the search to see all rows.':'No records for this view yet.';tr.append(td);body.append(tr)}else data.forEach(({r})=>{const tr=document.createElement('tr');r.forEach((v,i)=>{const td=document.createElement('td');td.dataset.label=t.heads[i];const span=document.createElement('span');span.textContent=v==null||v===''?'—':text(v);td.append(span);tr.append(td)});body.append(tr)});t.el.append(cap,head,body);t.count.textContent=data.length+' of '+t.data.length+' rows'}
function numericCell(v){if(typeof v==='number')return num(v);const s=text(v).trim();return /^\$?-?\d+(\.\d+)?(%|\/g|g)?$/.test(s)?num(s.replace(/[$%g/]/g,'')):null}
