function chart(id,dates,stores,rs,metric,percent=false){const series=stores.map(s=>dates.map(d=>metric(rs.filter(r=>r.store===s&&r.date===d)))),values=series.flat().filter(Number.isFinite),el=$(id);if(!values.length){el.innerHTML='<p class="empty">No numeric data for these filters.</p>';return}const w=600,h=250,left=58,right=18,top=20,bottom=40,max=values.reduce((m,v)=>Math.max(m,v),1)*1.1,x=i=>dates.length<2?(left+w-right)/2:left+i*(w-left-right)/(dates.length-1),y=v=>h-bottom-v*(h-top-bottom)/max;let svg='<svg viewBox="0 0 600 250" role="img" aria-labelledby="'+id+'-title"><title id="'+id+'-title">'+esc(el.closest('article').querySelector('h2').textContent)+'</title>';for(let i=0;i<=4;i++){const v=max*i/4;svg+='<line x1="'+left+'" y1="'+y(v)+'" x2="'+(w-right)+'" y2="'+y(v)+'" stroke="var(--line)"/><text x="'+(left-7)+'" y="'+(y(v)+4)+'" text-anchor="end">'+(percent?v.toFixed(0)+'%':'$'+v.toFixed(0))+'</text>'}dates.forEach((d,i)=>{if(i===0||i===dates.length-1||i===Math.floor((dates.length-1)/2))svg+='<text x="'+x(i)+'" y="'+(h-12)+'" text-anchor="middle">'+esc(d.slice(5)||d)+'</text>'});series.forEach((vs,i)=>{const points=vs.map((v,j)=>Number.isFinite(v)?[x(j),y(v),v,j]:null).filter(Boolean);svg+='<polyline fill="none" stroke="'+COLORS[i%6]+'" stroke-width="2.5" stroke-dasharray="'+(i>=6?'6 3':'none')+'" points="'+points.map(p=>p[0]+','+p[1]).join(' ')+'"/>';points.forEach(p=>{svg+='<circle cx="'+p[0]+'" cy="'+p[1]+'" r="3.5" fill="'+COLORS[i%6]+'"><title>'+esc(stores[i]+' · '+dates[p[3]]+' · '+(percent?p[2].toFixed(1)+'%':money(p[2])))+'</title></circle>'})});svg+='</svg><div class="legend">'+stores.map((s,i)=>'<span><i class="swatch" style="border-color:'+COLORS[i%6]+'"></i>'+esc(s)+'</span>').join('')+'</div><details><summary>View chart data</summary><div class="scroll"><table><caption>Missing observations are shown as —; lines connect available observations.</caption><thead><tr><th scope="col">Date</th>'+stores.map(s=>'<th scope="col">'+esc(s)+'</th>').join('')+'</tr></thead><tbody>'+dates.map((d,j)=>'<tr><td data-label="Date">'+esc(d)+'</td>'+series.map((s,i)=>'<td data-label="'+esc(stores[i])+'">'+(s[j]==null?'—':percent?s[j].toFixed(1)+'%':money(s[j]))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div></details>';el.innerHTML=svg}
function summary(rs,last){const now=rs.filter(r=>r.date===last),sales=now.filter(r=>r.base>0&&r.listed!=null&&r.listed<r.base-.005),best=sales.reduce((b,r)=>!b||r.listed/r.base<b.listed/b.base?r:b,null),priced=now.filter(r=>r.g>0&&r.at!=null).sort((a,b)=>a.at/a.g-b.at/b.g),cheap=priced[0],previous=[...new Set(rs.map(r=>r.date).filter(d=>d<last))].sort().pop(),key=r=>JSON.stringify([r.slug,r.brand,r.name]),old=new Map(rs.filter(r=>r.date===previous).map(r=>[key(r),r])),drops=now.filter(r=>r.listed!=null&&old.get(key(r))?.listed!=null&&r.listed<old.get(key(r)).listed-.005);const tiles=[['Best recorded deal',best?Math.round(100*(1-best.listed/best.base))+'% off':'—',best?best.store+' · '+best.name:'No sale prices in this view'],['Price drops',previous?drops.length:'—',previous?'Listed price vs '+previous+'; matched store/brand/name':'A prior comparable snapshot is needed'],['Lowest estimated $/g',cheap?pg(cheap.at,cheap.g):'—',cheap?cheap.store:'No after-tax size comparisons'],['Stores with priced items',new Set(now.map(r=>r.store)).size,last||'No dated snapshot']];$('summary').replaceChildren();tiles.forEach(([label,value,detail])=>{const tile=document.createElement('article');tile.className='tile';[['label',label],['value',value],['detail',detail]].forEach(([cls,v])=>{const span=document.createElement('span');span.className=cls;span.textContent=v;tile.append(span)});$('summary').append(tile)})}
