import type { DispensaryData } from '../data/load.ts';
import type { Item } from '../data/adapters.ts';
import { latestItemsWithHistory } from './history.ts';
export type CatalogItem = ReturnType<typeof latestItemsWithHistory>[number];
export type Filters = { search: string; store: string; type: string; minSize: number;
  includeLowThc: boolean; access: 'all' | 'medical' | 'rec'; saleOnly: boolean; dropsOnly: boolean };
export const defaultFilters: Filters = { search: '', store: '', type: '', minSize: 0,
  includeLowThc: false, access: 'all', saleOnly: false, dropsOnly: false };
export function matches(item: Item, filters: Filters) {
  const query = filters.search.trim().toLocaleLowerCase();
  return (!query || [item.name, item.brand, item.storeName, item.slug, item.deal].join(' ').toLocaleLowerCase().includes(query)) &&
    (!filters.store || item.storeId === filters.store) && (!filters.type || item.type === filters.type) &&
    (!filters.minSize || (!item.volumeSize && item.g !== null && item.g >= filters.minSize)) &&
    (filters.includeLowThc || item.thc === null || item.thc >= 75) &&
    (filters.access === 'all' || (filters.access === 'rec' ? item.recOnly === true : item.recOnly === false)) &&
    (!filters.saleOnly || item.discountPercent !== null);
}
export function perGram(item: Item) {
  const ratio = !item.volumeSize && item.g !== null && item.g > 0 && item.afterTax !== null && item.afterTax >= 0
    ? item.afterTax / item.g : null;
  return ratio !== null && Number.isFinite(ratio) ? ratio : null;
}
export const money = (n: number | null | undefined) => n !== null && n !== undefined && Number.isFinite(n)
  ? '$' + n.toFixed(2) : '—';
export const quantity = (n: number | null | undefined) => n === null || n === undefined ? '—' : String(n);
export function catalog(data: DispensaryData, filters: Filters) {
  return latestItemsWithHistory(data.snapshots).filter(item => matches(item, filters) &&
    (!filters.dropsOnly || item.comparison.drop !== null));
}
export function summarize(items: CatalogItem[]) {
  // Explicitly absent menu entries do not contribute to best-price claims.
  const available = items.filter(item => item.menuListed !== false);
  const valued = available.filter(item => perGram(item) !== null).sort((a, b) => perGram(a)! - perGram(b)!);
  const discounted = available.filter(item => item.discountPercent !== null)
    .sort((a, b) => b.discountPercent! - a.discountPercent!);
  const dropped = available.filter(item => item.comparison.drop !== null)
    .sort((a, b) => b.comparison.drop! - a.comparison.drop!);
  return { bestValue: valued[0] ?? null, bestDeal: discounted[0] ?? null, biggestDrop: dropped[0] ?? null,
    drops: dropped.length, vendors: new Set(available.map(item => item.storeId)).size };
}
export type SortValue = string | number | null;
export function sortRows<T>(rows: T[], value: (row: T) => SortValue, direction: 'asc' | 'desc') {
  return rows.map((row, index) => ({ row, index, value: value(row) })).sort((a, b) => {
    if (a.value === null || b.value === null) return a.value === b.value ? a.index - b.index : a.value === null ? 1 : -1;
    const order = typeof a.value === 'number' && typeof b.value === 'number' ? a.value - b.value :
      String(a.value).localeCompare(String(b.value), undefined, { numeric: true, sensitivity: 'base' });
    return (direction === 'asc' ? order : -order) || a.index - b.index;
  }).map(entry => entry.row);
}
export const WATCH = [{ brand: 'Cizi', gap: 30 }, { brand: 'Madlabs', gap: 21 }, { brand: 'Threddy', gap: 21 }];
export type Assumptions = { grams: number; uplift: number; target: number; cap: number };
export const defaultAssumptions: Assumptions = { grams: 2.8, uplift: 10, target: 42, cap: 50 };
export function plan(items: CatalogItem[], assumptions: Assumptions) {
  const { grams, uplift, target, cap } = assumptions;
  if (![grams, uplift, target, cap].every(Number.isFinite) || grams <= 0 || uplift < 0 || target < 0 || cap < 0)
    return null;
  const watched = (item: Item, brand: string) => (item.brand + ' ' + item.name).toLowerCase().includes(brand.toLowerCase());
  const candidates = items.filter(item => ['pod', 'cart', 'disposable'].includes(item.type) &&
    item.menuListed !== false && item.g !== null && item.g >= .5 && perGram(item) !== null && item.afterTax! > 0)
    .sort((a, b) => perGram(a)! - perGram(b)!);
  const withinCap = candidates.filter(item => item.afterTax! <= cap);
  const fallback = withinCap.filter(item => !WATCH.some(w => watched(item, w.brand))).slice(0, 5);
  const normalFallback = fallback.length ? perGram(fallback[0])! * grams : null;
  return { fallback, watch: WATCH.map(w => {
    const all = candidates.filter(item => watched(item, w.brand)), hit = withinCap.filter(item => watched(item, w.brand));
    const item = hit[0] ?? all[0] ?? null;
    if (!hit.length || !item) return { ...w, item, state: all.length ? 'over-cap' as const : 'absent' as const,
      units: null, cover: null, spend: null, bulkSpend: null, savings: null };
    const rate = grams / 14, coverage = (units: number) => units * item.g! / (rate * (1 + uplift / 100 * (units - 1)));
    // Preserve the original six-unit search limit; coverage uses actual item size.
    let units = 1; while (units < 6 && coverage(units) < w.gap) units++;
    units = Math.min(units, Math.floor(cap / item.afterTax!));
    const spend = perGram(item)! * grams, bulkSpend = spend * (1 + uplift / 100 * (units - 1));
    return { ...w, item, state: 'available' as const, units, cover: coverage(units), spend, bulkSpend,
      savings: normalFallback === null ? null : normalFallback - bulkSpend };
  }) };
}
