import type { Item, Snapshot } from '../data/adapters.ts';

export type Metric = 'basePerGram' | 'afterTaxPerGram' | 'discountPercent' | 'saleShare';
export const metricInfo: Record<Metric, { title: string; unit: '$/g' | '%' }> = {
  basePerGram: { title: 'Lowest base price per gram', unit: '$/g' },
  afterTaxPerGram: { title: 'Lowest estimated after-tax price per gram', unit: '$/g' },
  discountPercent: { title: 'Average discount on sale items', unit: '%' },
  saleShare: { title: 'Share of priced items on sale', unit: '%' },
};
export function paletteFor(slug: string) {
  let hash = 2166136261;
  for (const char of slug) hash = Math.imul(hash ^ char.charCodeAt(0), 16777619) >>> 0;
  // Identity, not filtered position, determines all three encodings.
  const hue = ((hash * .618033988749895 % 1) * 360).toFixed(3);
  return { color: `hsl(${hue} 65% 43%)`, darkColor: `hsl(${hue} 70% 70%)`,
    marker: hash % 5, dash: ['', '8 3', '3 3', '10 3 2 3'][Math.floor(hash / 5) % 4] };
}
function aggregate(items: Item[], metric: Metric): number | null {
  if (metric === 'saleShare') {
    const priced = items.filter(i => i.base !== null && i.base >= 0);
    return priced.length ? 100 * priced.filter(i => i.discountPercent !== null).length / priced.length : null;
  }
  const values = items.flatMap(i => {
    if (metric === 'discountPercent') return i.discountPercent === null || !Number.isFinite(i.discountPercent) ? [] : [i.discountPercent];
    const price = metric === 'basePerGram' ? i.base : i.afterTax;
    if (i.volumeSize || i.g === null || i.g <= 0 || price === null || price < 0) return [];
    const ratio = price / i.g;
    return Number.isFinite(ratio) ? [ratio] : [];
  });
  if (!values.length) return null;
  return metric === 'discountPercent' ? values.reduce((a, b) => a + b / values.length, 0) :
    values.reduce((a, b) => Math.min(a, b), Infinity);
}
export function buildChart(snapshots: Snapshot[], metric: Metric, predicate: (item: Item) => boolean = () => true) {
  const ordered = [...snapshots].sort((a, b) => a.date.localeCompare(b.date));
  const dates = [...new Set(ordered.map(s => s.date))];
  const vendors = new Map<string, string>();
  for (const snapshot of ordered) for (const store of snapshot.stores)
    if (store.slug) vendors.set(store.slug, store.name + (store.recOnly ? ' (rec only)' : ''));
  const series = [...vendors].sort(([a], [b]) => a.localeCompare(b)).map(([slug, name]) => ({
    slug, name, ...paletteFor(slug), values: dates.map(date => aggregate(
      ordered.filter(s => s.date === date).flatMap(s => s.stores.filter(st => st.slug === slug)
        .flatMap(st => st.items)).filter(predicate), metric)),
  }));
  return { metric, ...metricInfo[metric], dates, series };
}
export type ChartData = ReturnType<typeof buildChart>;
