import { useEffect, useRef, useState } from 'react';
import { loadDispensary, type DispensaryData } from './data/load.ts';
export function useDispensary() {
  const [data, setData] = useState<DispensaryData | null>(null), [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null), [revision, setRevision] = useState(0);
  const request = useRef(0);
  useEffect(() => {
    const controller = new AbortController(), generation = ++request.current;
    setLoading(true); setError(null);
    loadDispensary({ signal: controller.signal }).then(value => {
      if (!controller.signal.aborted && request.current === generation) setData(value);
    }).catch(reason => {
      if (!controller.signal.aborted && request.current === generation)
        setError(reason instanceof Error ? reason.message : 'Unable to load data');
    }).finally(() => { if (!controller.signal.aborted && request.current === generation) setLoading(false); });
    return () => controller.abort();
  }, [revision]);
  return { data, loading, error, reload: () => setRevision(n => n + 1) };
}
