import { useId, useState, type ReactNode } from 'react';
import { sortRows, type SortValue } from '../model/catalog.ts';
import { Button, Empty } from './ui.tsx';
export type Column<T> = { key: string; label: string; value: (row: T) => SortValue;
  render?: (row: T) => ReactNode };
export function SortableTable<T>({ rows, columns, rowKey, caption, initialSort, initialDirection = 'asc', detail, emptyMessage }:
  { rows: T[]; columns: Column<T>[]; rowKey: (row: T) => string; caption: string;
    initialSort?: string; initialDirection?: 'asc' | 'desc'; detail?: (row: T) => ReactNode; emptyMessage?: string }) {
  const id = useId(), [sort, setSort] = useState(initialSort ?? columns[0].key);
  const [direction, setDirection] = useState<'asc' | 'desc'>(initialDirection), [page, setPage] = useState(0);
  const size = 25, pages = Math.max(1, Math.ceil(rows.length / size)), current = Math.min(page, pages - 1);
  const column = columns.find(c => c.key === sort) ?? columns[0];
  const ordered = sortRows(rows, column.value, direction).slice(current * size, (current + 1) * size);
  function choose(key: string) { setSort(key); setDirection(key === sort && direction === 'asc' ? 'desc' : 'asc'); setPage(0); }
  if (!rows.length) return <Empty>{emptyMessage ?? 'No matching records. Change the filters or wait for another collection run.'}</Empty>;
  return <>
    <div className="d-table-scroll" role="region" aria-label={caption + ' — scroll horizontally'} tabIndex={0}>
      <table className="d-table"><caption>{caption}</caption><thead><tr>{columns.map(c =>
        <th key={c.key} scope="col" aria-sort={sort === c.key ? direction === 'asc' ? 'ascending' : 'descending' : 'none'}>
          <button type="button" onClick={() => choose(c.key)}>{c.label}<span aria-hidden="true"> {sort === c.key ? direction === 'asc' ? '↑' : '↓' : '↕'}</span></button>
        </th>)}{detail && <th scope="col">Details</th>}</tr></thead><tbody>{ordered.map(row =>
          <tr key={rowKey(row)}>{columns.map(c => <td key={c.key}>{c.render ? c.render(row) : c.value(row) ?? '—'}</td>)}
            {detail && <td><details><summary>View item</summary><div className="d-item-detail">{detail(row)}</div></details></td>}
          </tr>)}</tbody></table>
    </div>
    <div className="d-pagination" aria-label={caption + ' pagination'}>
      <span id={id} aria-live="polite">{current * size + 1}–{Math.min((current + 1) * size, rows.length)} of {rows.length}</span>
      <Button aria-describedby={id} disabled={!current} onClick={() => setPage(current - 1)}>Previous</Button>
      <Button aria-describedby={id} disabled={current === pages - 1} onClick={() => setPage(current + 1)}>Next</Button>
    </div>
  </>;
}
