          <path d={path} fill="none" stroke="currentColor" strokeWidth={selected.has(s.slug)?2.5:1} strokeDasharray={s.dash} />
          {s.values.map((v,i) => v === null ? null : <g key={data.dates[i]} fill="currentColor"><title>{`${s.name} · ${data.dates[i]} · ${valueText(v,data.unit)}`}</title><Marker kind={s.marker} x={x(i)} y={y(v)} size={selected.has(s.slug)?4:2} /></g>)}
        </g>;
      })}
    </svg> : <p className="d-empty">No numeric observations match these filters.</p>}
    <div className="d-legend-tools"><label htmlFor={`${id}-search`}>Find vendor<input id={`${id}-search`} type="search" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Vendor name or slug" /></label>
      <button type="button" onClick={()=>change(new Set(data.series.map(s=>s.slug)))}>Select all</button><button type="button" onClick={()=>change(new Set())}>Clear selection</button>
      <span role="status">{selectedCount} of {data.series.length} highlighted · {visible.length} vendor buttons shown</span></div>
    <div className="d-legend" role="group" aria-label={`${data.title}: vendor highlights`} tabIndex={0}>
      {visible.map(s=><button type="button" key={s.slug} className="d-legend-button" aria-pressed={selected.has(s.slug)} onClick={()=>toggle(s.slug)}>
        <svg aria-hidden="true" viewBox="0 0 34 18" width="34" height="18" className="d-series" style={vendorStyle(s)}><path d="M0 9H34" fill="none" stroke="currentColor" strokeWidth="2" strokeDasharray={s.dash}/><g fill="currentColor"><Marker kind={s.marker} x={17} y={9} /></g></svg><span>{s.name}</span>
      </button>)}{!visible.length&&<p className="d-empty">No vendor names match this search.</p>}
    </div>
    <details className="d-chart-data"><summary>Exact chart data ({data.series.length} vendors)</summary><div className="d-table-scroll" tabIndex={0} role="region" aria-label={`${data.title}: complete data table`}>
      <table><caption>{data.title}. All vendors are included regardless of highlight selection. — means no observation.</caption><thead><tr><th scope="col">Date</th>{data.series.map(s=><th scope="col" key={s.slug}>{s.name}</th>)}</tr></thead><tbody>{data.dates.map((date,i)=><tr key={date}><th scope="row">{date}</th>{data.series.map(s=><td key={s.slug}>{valueText(s.values[i]??null,data.unit)}</td>)}</tr>)}</tbody></table>
    </div></details>
  </section>;
}
