import { useState } from 'react';
import { defaultAssumptions, money, perGram, plan, type CatalogItem, type Assumptions } from '../model/catalog.ts';
import { Card, Empty } from './ui.tsx';
import { SortableTable } from './SortableTable.tsx';
export function Planner({ items }: { items: CatalogItem[] }) {
  const [assumptions, setAssumptions] = useState<Assumptions>(defaultAssumptions);
  const result = plan(items, assumptions);
  return <Card id="planner"><h2>Spend scenarios</h2><p className="d-muted">Uses the currently filtered catalog and estimated after-tax prices. Unknown THC is retained and marked. This is a cost model using your assumptions, not a consumption or purchase recommendation.</p>
    <div className="d-filters">{([
      ['grams', 'Grams / 2 weeks', .1], ['uplift', 'Extra use / extra unit (%)', 1],
      ['target', 'Spend target / 2 weeks ($)', 1], ['cap', 'One-time cap ($)', 1],
    ] as const).map(([key, label, step]) => <label key={key}>{label}<input type="number" min={key === 'grams' ? .1 : 0} step={step}
      value={Number.isFinite(assumptions[key]) ? assumptions[key] : ''} onChange={e => setAssumptions(a => ({ ...a, [key]: e.target.value === '' ? NaN : Number(e.target.value) }))} /></label>)}</div>
    <p className="d-muted">Cizi: 30-day gap prior; Madlabs and Threddy: 21-day priors. These are your estimates, not learned cadence. Coverage accounts for each item's actual gram size; the search is limited to six units and your cap.</p>
    {!result ? <Empty>Enter positive grams and non-negative assumptions to calculate scenarios.</Empty> : <>
      <SortableTable rows={result.watch} caption="Watched-brand scenarios" rowKey={w => w.brand} columns={[
        { key: 'brand', label: 'Brand', value: w => w.brand }, { key: 'state', label: 'Menu status', value: w => w.state,
          render: w => w.state === 'absent' ? 'No qualifying entry' : w.state === 'over-cap' ? 'Above cap' : 'On menu' },
        { key: 'item', label: 'Lowest $/g item', value: w => w.item?.name ?? null,
          render: w => w.item ? <>{w.item.name}<span className="d-muted d-block">{w.item.storeName} · {money(w.item.afterTax)} · {w.item.thc === null ? 'THC unknown' : Math.round(w.item.thc) + '% THC'}</span></> : '—' },
        { key: 'spend', label: 'Normal / 2 weeks', value: w => w.spend, render: w => money(w.spend) },
        { key: 'bulk', label: 'With extra use', value: w => w.bulkSpend, render: w => money(w.bulkSpend) },
        { key: 'cover', label: 'Scenario', value: w => w.cover, render: w => w.units === null ? 'No in-cap scenario' :
          <>{w.units} unit(s), {money(w.units * w.item!.afterTax!)}; ~{Math.round(w.cover!)} days, vs {w.gap}-day prior.
            <span className="d-muted d-block">{w.savings === null ? 'No fallback comparison.' : w.savings > 0 ? money(w.savings) + ' less / 2 weeks than fallback.' : money(-w.savings) + ' more / 2 weeks than fallback.'}</span></> },
      ]} />
      <SortableTable rows={result.fallback} caption="Lowest-cost non-watchlist items within cap" rowKey={i => i.rowId} initialSort="pg" columns={[
        { key: 'store', label: 'Store', value: i => i.storeName }, { key: 'item', label: 'Item', value: i => i.name },
        { key: 'g', label: 'Grams', value: i => i.g }, { key: 'thc', label: 'THC (%)', value: i => i.thc },
        { key: 'tax', label: 'After tax estimate', value: i => i.afterTax, render: i => money(i.afterTax) },
        { key: 'pg', label: '$/g', value: perGram, render: i => money(perGram(i)) },
        { key: 'spend', label: 'Est. / 2 weeks', value: i => perGram(i)! * assumptions.grams,
          render: i => <>{money(perGram(i)! * assumptions.grams)} · {perGram(i)! * assumptions.grams <= assumptions.target ? 'Within' : 'Above'} target</> },
      ]} />
    </>}
  </Card>;
}
