        <TrendChart data={trend} highlighted={selected} onHighlightChange={setHighlighted} />
        <label className="d-metric">Deal metric<select value={dealMetric} onChange={e => setDealMetric(e.target.value as Metric)}>{(['discountPercent', 'saleShare'] as Metric[]).map(k => <option key={k} value={k}>{metricInfo[k].title}</option>)}</select></label>
        <TrendChart data={discountTrend} highlighted={selected} onHighlightChange={setHighlighted} />
