        <SortableTable rows={stores.filter(s => s.slug && selected.has(s.slug))} rowKey={s => s.id} caption="Value, deals and learning at the same vendor" columns={[
          { key: 'store', label: 'Store', value: s => s.name },
          { key: 'value', label: 'Latest estimated $/g', value: s => summarize(items.filter(i => i.slug === s.slug)).bestValue ? perGram(summarize(items.filter(i => i.slug === s.slug)).bestValue!) : null, render: s => money(summarize(items.filter(i => i.slug === s.slug)).bestValue ? perGram(summarize(items.filter(i => i.slug === s.slug)).bestValue!) : null) },
          { key: 'sale', label: 'Largest menu discount', value: s => summarize(items.filter(i => i.slug === s.slug)).bestDeal?.discountPercent ?? null, render: s => { const deal = summarize(items.filter(i => i.slug === s.slug)).bestDeal; return deal ? deal.discountPercent!.toFixed(0) + '%' : '—'; } },
          { key: 'learning', label: 'Cadence context', value: s => data.sources.cadence.state === 'ready' ? data.cadence.brands.filter(c => c.store === s.slug).length : null, render: s => data.sources.cadence.state !== 'ready' ? 'Unavailable' : data.cadence.brands.filter(c => c.store === s.slug).map(c => (c.brand ?? 'Unknown brand') + ': ' + (c.learned === true ? c.medianGapDays === null ? 'learned, median unknown' : 'learned ~' + c.medianGapDays + ' days' : c.prior.lo === null ? 'insufficient data' : 'prior ' + c.prior.lo + (c.prior.hi === null ? '+' : '–' + c.prior.hi) + ' days')).join('; ') || 'No cadence records' },
          { key: 'deals', label: 'Recurring titles', value: s => data.sources.deals.state === 'ready' ? data.deals.deals.filter(d => d.store === s.slug && d.recurring === true).length : null, render: s => data.sources.deals.state !== 'ready' ? 'Unavailable' : data.deals.deals.filter(d => d.store === s.slug && d.recurring === true).map(d => d.title ?? 'Untitled').join('; ') || 'None observed' },
        ]} />
        <div className="d-signal-strip"><p><Badge tone="insight">Learned context</Badge> {data.sources.cadence.state === 'ready' ? data.cadence.brands.filter(c => c.learned === true && (!filters.store || c.store === filters.store)).length + ' learned cadence records.' : 'Cadence source unavailable.'} {data.sources.deals.state === 'ready' ? data.deals.deals.filter(d => d.recurring === true && (!filters.store || d.store === filters.store)).length + ' recurring deal titles.' : 'Deal patterns unavailable.'} <a href="#insights">Inspect observations</a>.</p>
          <p><Badge tone="positive">Size value</Badge> {data.latest?.halfValue.available ? data.latest.halfValue.pairs.filter(p => p.split_wins === true && (!filters.store || p.store === filters.store)).length + ' same-product split-buy wins captured.' : 'Half-value source unavailable.'} <a href="#half-value">Compare sizes</a>.</p></div>
      </Card>
      <Card id="catalog"><h2>Latest menu items</h2><p className="d-muted">Sort any column; missing values sort last. Swipe the table on small screens. Open a row for source fields and comparison limits.</p>
        <SortableTable rows={items} columns={columns} rowKey={i => i.rowId} caption={'Menu items — ' + (data.latest?.date ?? 'date unknown')} initialSort="pg" detail={i => <ItemDetail item={i} />} />
      </Card>
      <Insights data={data} filters={filters} /><Planner items={items} />
      <Card><h2>Data limits</h2><ul><li>No stock counts. A menu listing is not confirmation of physical availability.</li>
        <li>Weedmaps deal coverage is incomplete. Harvest's own-site deals are not readable by this collector.</li>
        <li>In-store-only offers come from manual entries in data/manual.json.</li>
        <li>Listed is the captured menu price. Original is the captured pre-sale price. After-tax values are the collector's estimates using excise and sales tax, without first-visit promotions.</li>
        <li>Missing original prices do not establish a discount. No new tax or legal eligibility assumptions are calculated here.</li></ul></Card>
    </>}
  </div>;
}
