&#x20;\<label>Max one-time purchase ($) \<input id="cap" type="number" value="50" style="width:60px">\</label>\</div>
&#x20;\<h2>Cheap-brand watchlist\</h2>\<table id="wl">\</table>
&#x20;\<div class="note">Buy-now signal: a watched brand appears on any menu. Consumption default: about 5 days per gram, or 2.8g per 2 weeks. His past $42 per 2 weeks at $11/g implies about 3.8g, so the $42 may include other spend. Bulk buying raises use by the % above for each extra unit. Gap lengths are the user's restock priors (Cizi 30 days, Threddy and Madlabs 21 days), not measured yet.\</div>
&#x20;\<h2>Fallback: cheapest available now\</h2>\<table id="fb">\</table>
\</section>
\<section id="half" class="tab">
&#x20;\<div class="note">When is 2 x 0.5g cheaper than 1 x 1g? After-tax prices, same store. Rec-only stores are comparison data, not part of the medical set.\</div>
&#x20;\<h2>Callout\</h2>\<div id="hcall">\</div>
&#x20;\<h2>Same product in 0.5g and 1g (latest snapshot)\</h2>\<table id="hpairs">\</table>
&#x20;\<h2>Cheapest 0.5g vs cheapest 1g by type (effective $/g)\</h2>\<table id="htypes">\</table>
\</section>
\<h2>Menu availability (registry)\</h2>\<div id="reg" class="note">\</div>
\</main>
\<script>
/\* Data layout (all under data/):
&#x20;manifest.json       {"dates":["YYYY-MM-DD",...]}
&#x20;snapshots/DATE.json scout snapshot {date, stores:[{slug, listing:{name,...}, volume_deal_items:[], items:[{name,brand,listed,original,after_tax,deal,in_stock_on_menu,...}]}]}
&#x20;registry.json       {"store:id":{name,first_seen,last_seen,days_seen:[...],last_listed}}
&#x20;manual.json         array of {date,store,name,price,after_tax?,deal_text?,in_store_only?,size_g?}  (hand-added)
&#x20;Reserved for the later buy-timing view: stock gaps come from registry.days_seen; consumption inputs are in README.md. \*/
const COL=['#1f77b4','#d62728','#2ca02c','#ff7f0e','#9467bd','#8c564b'];
const $=id=>document.getElementById(id);let charts={},snaps=[],reg={},man=[];
async function j(u,d){try{const r=await fetch(u,{cache:'no-store'});return r.ok?await r.json():d}catch(e){return d}}
const num=x=>x==null||isNaN(+x)?null:+x,avg=a=>a.length?+(a.reduce((x,y)=>x+y,0)/a.length).toFixed(2):null,mn=a=>a.length?+Math.min(...a).toFixed(2):null;
function size(n){const m=/(\d\*\\.?\d+)\s\*(g|gram|ml)\b/i.exec(n||'');return m?+m[1]:null}
const pg=(p,g)=>p!=null&&g?'$'+(p/g).toFixed(2)+'/g':'';const sz=g=>g==null?'?':g+'g';const th=t=>t==null?'THC ?':Math.round(t)+'% THC';
function typ(n){n=n||'';return /disposable|all.in.one|\baio\b|device/i.test(n)?'disposable':/\bpod\b/i.test(n)?'pod':/cart/i.test(n)?'cart':'other'}
function rows(){const o=[];snaps.forEach(s=>s.stores.forEach(st=>(st.items||[]).forEach(i=>{const g=size(i.name),base=num(i.original)??num(i.listed),tv=num(i.thc),tp=!tv?null:(tv>100?(g?tv/(g\*10):null):tv);
&#x20;if(base==null)return;if(tp!=null&&tp<75&&!$('lowthc').checked)return;o.push({thc:tp,date:s.date,store:(st.listing?.name||st.slug)+(st.rec_only?' (rec only)':''),slug:st.slug,name:i.name,brand:i.brand,type:typ(i.name),g,base,listed:num(i.listed),at:num(i.after_tax),deal:i.deal,stock:i.in_stock_on_menu})})));return o}
function filt(r){const t=$('typ').value,m=+$('sz').value;return r.filter(x=>(!t||x.type==t)&&(m==0||(x.g!=null&&x.g>=m)))}
function mk(id,cfg){if(charts[id])charts[id].destroy();charts[id]=new Chart($(id),cfg)}
function ser(rs,dates,f,stores){return stores.map((s,i)=>({label:s,borderColor:COL[i%6],backgroundColor:COL[i%6],spanGaps:true,tension:.2,pointRadius:4,data:dates.map(d=>f(rs.filter(r=>r.store==s&&r.date==d)))}))}
function render(){const all=rows(),rs=filt(all),dates=[...new Set(all.map(r=>r.date))].sort(),stores=[...new Set(all.map(r=>r.store))];
&#x20;const L=(id,ds,x={})=>mk(id,{type:'line',data:{labels:dates,datasets:ds},options:{maintainAspectRatio:false,...x}});
&#x20;L('c1',ser(rs,dates,a=>mn(a.map(r=>r.base)),stores));
&#x20;L('c2',ser(rs,dates,a=>mn(a.filter(r=>r.g).map(r=>r.base/r.g)),stores));
&#x20;const last=dates[dates.length-1];
&#x20;$('bt').innerHTML='\<tr>\<th>Store\</th>\<th>Items\</th>\<th>Min $/g after tax\</th>\<th>Min after tax\</th>\<th>Avg base\</th>\<th>Avg listed\</th>\<th>Avg after tax\</th>\</tr>'+stores.map(s=>{const a=rs.filter(r=>r.store==s&&r.date==last);return \`\<tr>\<td>${s}\</td>\<td>${a.length}\</td>\<td>\<b>${mn(a.filter(r=>r.at!=null&&r.g).map(r=>r.at/r.g))??'-'}\</b>\</td>\<td>\<b>${mn(a.filter(r=>r.at!=null).map(r=>r.at))??'-'}\</b>\</td>\<td>${avg(a.map(r=>r.base))??'-'}\</td>\<td>${avg(a.filter(r=>r.listed!=null).map(r=>r.listed))??'-'}\</td>\<td>${avg(a.filter(r=>r.at!=null).map(r=>r.at))??'-'}\</td>\</tr>\`}).join('');
&#x20;const sale=r=>r.listed!=null&&r.listed\<r.base-0.005;
&#x20;L('c3',ser(rs,dates,a=>a.length?+(100\*a.filter(sale).length/a.length).toFixed(1):null,stores),{scales:{y:{title:{display:true,text:'% of items'}}}});
&#x20;L('c4',ser(rs,dates,a=>avg(a.filter(sale).map(r=>100\*(1-r.listed/r.base))),stores),{scales:{y:{title:{display:true,text:'% off'}}}});
&#x20;const ls=snaps[snaps.length-1];
&#x20;$('ann').innerHTML=ls?ls.stores.map(st=>{const a=(st.listing?.announcement||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim(),v=(st.volume_deal_items||[]).length;return \`\<div>\<b>${st.listing?.name||st.slug}\</b>: ${a||'no announcement'}${v?\` (${v} volume-deal items)\`:''}${(st.items||[]).length?'':' \<i>(no items captured)\</i>'}\</div>\`}).join(''):'';
&#x20;const dd=rs.filter(r=>r.date==last&&sale(r)).sort((a,b)=>(a.listed/a.base)-(b.listed/b.base)).slice(0,15).map(r=>({d:r.date,s:r.store,n:r.name+' ('+sz(r.g)+', '+th(r.thc)+')',pg:pg(r.at??r.listed,r.g),b:r.base,l:r.listed,a:r.at,t:(100\*(1-r.listed/r.base)).toFixed(0)+'% off'+(r.deal?' - '+r.deal:''),src:'scout'}));
&#x20;const mm=man.map(m=>({d:m.date,s:m.store,n:m.name,pg:pg(m.after_tax??m.price,m.size_g),b:'',l:m.price,a:m.after_tax??'',t:(m.deal_text||'')+(m.in_store_only?' (in-store only)':''),src:'manual'}));
&#x20;$('dt').innerHTML='\<tr>\<th>Date\</th>\<th>Store\</th>\<th>Item\</th>\<th>Base\</th>\<th>Listed\</th>\<th>After tax\</th>\<th>Per gram\</th>\<th>Deal\</th>\<th>Src\</th>\</tr>'+[...mm,...dd].map(r=>\`\<tr>\<td>${r.d}\</td>\<td>${r.s}\</td>\<td>${r.n}\</td>\<td>${r.b}\</td>\<td>${r.l??''}\</td>\<td>${r.a??''}\</td>\<td>${r.pg||''}\</td>\<td>${r.t}\</td>\<td>${r.src}\</td>\</tr>\`).join('');
&#x20;buy(all);half();const R=Object.entries(reg),gone=R.filter(([k,v])=>v.last_seen!=last);
&#x20;$('reg').textContent=\`${R.length} items tracked since ${R.map(([k,v])=>v.first_seen).sort()[0]||'-'}. ${gone.length} not on the menu in the latest snapshot. Restock and stock-gap patterns appear as days accumulate.\`}

function half(){const ls=snaps[snaps.length-1],h=ls&&ls.half_value,nm=slug=>{const st=ls.stores.find(x=>x.slug==slug);return (st?.listing?.name||slug)+(st?.rec_only?' (rec only)':'')};
&#x20;if(!h){$('hcall').textContent='No 0.5g data in the latest snapshot yet. It appears after the next daily run.';$('hpairs').innerHTML='';$('htypes').innerHTML='';return}
&#x20;const win=h.pairs.filter(p=>p.split_wins),tw=h.types.filter(t=>t.split_wins);
&#x20;$('hcall').innerHTML=win.length||tw\.length?'\<b style="color:#1a7f37">Split buy wins now:\</b> '+[...win.map(p=>\`${nm(p.store)}: ${p.name} (2x0.5g $${p.two_halves_at} vs 1g $${p.one_g_at}, saves $${p.save})\`),...tw\.map(t=>\`${nm(t.store)} ${t.type}: 0.5g at $${t.half_pg}/g vs 1g at $${t.one_pg}/g\`)].join('; '):\`No split-buy wins in the latest snapshot (${h.pair_count} same-product 0.5g/1g pairs, ${h.types.length} type comparisons).\`;
&#x20;$('hpairs').innerHTML='\<tr>\<th>Store\</th>\<th>Product\</th>\<th>0.5g\</th>\<th>2 x 0.5g\</th>\<th>1g\</th>\<th>Split saves\</th>\</tr>'+(h.pairs.length?h.pairs.map(p=>\`\<tr>\<td>${nm(p.store)}\</td>\<td>${p.name}\</td>\<td>$${p.half_at}\</td>\<td>$${p.two_halves_at}\</td>\<td>$${p.one_g_at}\</td>\<td style="color:${p.split_wins?'#1a7f37':'#a00'}">${p.save>0?'$'+p.save:'no ($'+p.save+')'}\</td>\</tr>\`).join(''):'\<tr>\<td colspan="6">No product is listed in both sizes at one store today.\</td>\</tr>');
&#x20;$('htypes').innerHTML='\<tr>\<th>Store\</th>\<th>Type\</th>\<th>Cheapest 0.5g\</th>\<th>$/g\</th>\<th>Cheapest 1g\</th>\<th>$/g\</th>\<th>Better\</th>\</tr>'+h.types.map(t=>\`\<tr>\<td>${nm(t.store)}\</td>\<td>${t.type}\</td>\<td>${t.half_item}\</td>\<td>$${t.half_pg}\</td>\<td>${t.one_item}\</td>\<td>$${t.one_pg}\</td>\<td>${t.split_wins?'\<b style="color:#1a7f37">2 x 0.5g\</b>':'1g'}\</td>\</tr>\`).join('')}
const WATCH=[['Cizi',30],['Madlabs',21],['Threddy',21]];
function buy(all){const last=[...new Set(all.map(r=>r.date))].sort().pop(),u=+$('u2w').value||2.8,up=(+$('upl').value||0)/100,tgt=+$('tgt').value||42,r=u/14;
&#x20;const cap0=+$('cap').value||50,candAll=all.filter(x=>x.date==last&&['pod','disposable','cart'].includes(x.type)&&x.g!=null&&x.g>=0.5&&x.at!=null&&x.stock!==false).sort((a,b)=>a.at/a.g-b.at/b.g),cand=candAll.filter(x=>x.at<=cap0);
&#x20;const fbk=cand.filter(x=>!WATCH.some(w=>new RegExp(w[0],'i').test((x.brand||'')+' '+x.name)));const fb=fbk[0];
&#x20;const fbDay=fb?fb.at/fb.g\*r:null;
&#x20;$('fb').innerHTML='\<tr>\<th>Store\</th>\<th>Item\</th>\<th>Size\</th>\<th>THC\</th>\<th>After tax\</th>\<th>$/g\</th>\<th>Est. spend / 2 wk\</th>\<th>vs target\</th>\</tr>'+fbk.slice(0,5).map(x=>{const s=(x.at/x.g\*u).toFixed(2);return \`\<tr>\<td>${x.store}\</td>\<td>${x.name}\</td>\<td>${sz(x.g)}\</td>\<td>${th(x.thc)}\</td>\<td>${x.at}\</td>\<td>${(x.at/x.g).toFixed(2)}\</td>\<td>$${s}\</td>\<td>${s<=tgt?'under':'over'} $${tgt}\</td>\</tr>\`}).join('');
&#x20;$('wl').innerHTML='\<tr>\<th>Brand\</th>\<th>Status\</th>\<th>Cheapest now\</th>\<th>Spend / 2 wk\</th>\<th>Plan\</th>\</tr>'+WATCH.map(([b,gap])=>{const re=new RegExp(b,'i'),hit=cand.filter(x=>re.test((x.brand||'')+' '+x.name)),hitAll=candAll.filter(x=>re.test((x.brand||'')+' '+x.name));
&#x20; if(!hit.length&&hitAll.length){const c=hitAll[0];return \`\<tr>\<td>${b}\</td>\<td>On menu: ${[...new Set(hitAll.map(x=>x.store))].join(', ')}\</td>\<td>${c.name} at ${c.store}: $${c.at}\</td>\<td>-\</td>\<td>Every listed unit is over the $${cap0} one-time cap. No buy.\</td>\</tr>\`}
&#x20; if(!hit.length){const seen=all.filter(x=>re.test((x.brand||'')+' '+x.name)).map(x=>x.date).sort().pop();return \`\<tr>\<td>${b}\</td>\<td>Not on any menu${seen?' (last seen '+seen+')':''}\</td>\<td>-\</td>\<td>-\</td>\<td>Wait. Use fallback. Expected back about every ${gap} days.\</td>\</tr>\`}
&#x20; const c=hit[0],pd=c.at/c.g,cap=+$('cap').value||50;let n=1;for(n=1;n<6;n++){if(n/(r\*(1+up\*(n-1)))>=gap)break}
&#x20; const nCap=Math.floor(cap/c.at);let capNote='';if(nCap<1){return \`\<tr>\<td>${b}\</td>\<td>On menu: ${[...new Set(hit.map(x=>x.store))].join(', ')}\</td>\<td>${c.name} at ${c.store}: $${c.at}\</td>\<td>-\</td>\<td>Over the $${cap} one-time cap even for 1 unit. No buy.\</td>\</tr>\`}if(n>nCap){n=nCap;capNote=\` Capped at ${n} unit(s) = $${(n\*c.at).toFixed(2)} (max one-time spend $${cap}).\`}
&#x20; const f=1+up\*(n-1),perDay=pd\*r\*f,cover=Math.round(n/(r\*f)),save=fbDay!=null?(fbDay-perDay)\*14:null,where=[...new Set(hit.map(x=>x.store))].join(', '),item=\`${c.name} at ${c.store}: $${c.at} ($${pd.toFixed(2)}/g)\`;
&#x20; if(save!=null&&save<=0)return \`\<tr>\<td>${b}\</td>\<td>On menu: ${where}\</td>\<td>${item}\</td>\<td>$${(pd\*u).toFixed(2)}\</td>\<td>Not cheaper than the fallback (about $${(-save/f).toFixed(2)} more per 2 weeks at normal use). No stock-up.\</td>\</tr>\`;
&#x20; return \`\<tr>\<td>\<b>${b}\</b>\</td>\<td>\<b>BUY NOW\</b> - on ${where}\</td>\<td>${item}\</td>\<td>$${(pd\*u).toFixed(2)} normal use, $${(perDay\*14).toFixed(2)} with bulk use\</td>\<td>Buy ${n} unit(s): about ${cover} days of use vs ${gap}-day expected gap.${capNote}${save!=null?\` Saves about $${save.toFixed(2)} per 2 weeks vs fallback.\`:''}\</td>\</tr>\`}).join('')}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('nav button,.tab').forEach(e=>e.classList.remove('on'));b.classList.add('on');$(b.dataset.t).classList.add('on');render()});
(async()=>{const mf=await j('data/manifest.json',{dates:[]});snaps=(await Promise.all(mf.dates.slice(-14).map(d=>j('data/snapshots/'+d+'.json',null)))).filter(Boolean);
&#x20;reg=await j('data/registry.json',{});man=await j('data/manual.json',[]);if(!Array.isArray(man))man=man.entries||[];
&#x20;const all=rows();$('typ').innerHTML='\<option value="">All types\</option>'+['disposable','pod','cart','other'].map(t=>\`\<option>${t}\</option>\`).join('');
&#x20;$('typ').onchange=$('sz').onchange=$('lowthc').onchange=render;['u2w','upl','tgt','cap'].forEach(i=>$(i).onchange=render);$('meta').textContent=snaps.length?\`${snaps.length} daily snapshot(s), latest ${snaps[snaps.length-1].date}, ${all.length} priced items\`:'No snapshots yet';render()})();
\</script>\</body>\</html>

\=== CURRENT dispensary/learned.html ===
\<!doctype html>
\<html lang="en">\<head>\<meta charset="utf-8">\<meta name="viewport" content="width=device-width,initial-scale=1">
\<title>Dispensary: learned patterns\</title>
\<!-- Authored by Instinct -->
\<style>
body{font:15px/1.4 system-ui,sans-serif;margin:0 auto;max-width:900px;padding:16px;color:#222}
h1{font-size:20px;margin:0 0 4px}h2{font-size:16px;margin:24px 0 6px}
table{border-collapse:collapse;width:100%;font-size:13px}th,td{border-bottom:1px solid #ddd;padding:5px 6px;text-align:left;vertical-align:top}
.note{color:#666;font-size:13px}.pri{color:#b00020;font-weight:600}.fyi{color:#8a6d00}
.scroll{overflow-x:auto}
\</style>\</head>\<body>
\<a href="./">&larr; Prices\</a>
\<h1>Learned patterns\</h1>
\<div class="note" id="meta">Loading...\</div>
\<h2>Latest alerts\</h2>\<div class="scroll">\<table id="al">\</table>\</div>
\<h2>Restock cadence (brands that have been in the cheap tier)\</h2>
\<div class="note">Gap = consecutive days a brand was absent at a store. Until 3 gaps are seen, your own estimates are shown as the prior.\</div>
\<div class="scroll">\<table id="cad">\</table>\</div>
\<h2>Recurring deal titles\</h2>\<div class="scroll">\<table id="deal">\</table>\</div>
\<script>
const g=u=>fetch('data/'+u,{cache:'no-store'}).then(r=>r.ok?r.json():null).catch(()=>null);
const esc=s=>String(s??'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
const rows=(el,head,body)=>{el.innerHTML='\<tr>'+head.map(h=>'\<th>'+h+'\</th>').join('')+'\</tr>'+(body.length?body.map(r=>'\<tr>'+r.map(c=>'\<td>'+c+'\</td>').join('')+'\</tr>').join(''):'\<tr>\<td colspan="'+head.length+'" class="note">Nothing yet. Data builds up daily.\</td>\</tr>')};
(async()=>{
&#x20;const [st,cad,dp]=await Promise.all([g('status.json'),g('cadence.json'),g('deal_patterns.json')]);
&#x20;document.getElementById('meta').textContent=st?('Last run '+(st.date||'?')+(st.ok?'':' (FAILED: '+esc(st.error)+')')):'No collector data yet.';
&#x20;rows(document.getElementById('al'),['Level','Rule','Store','Item','Listed','Was'],((st&&st.alerts)||[]).map(a=>['\<span class="'+(a.level=='priority'?'pri':a.level=='fyi'?'fyi':'')+'">'+esc(a.level)+'\</span>',esc(a.rule+' ('+a.change+')'),esc(a.slug),esc(a.name),esc(a.listed),esc(a.was)]));
&#x20;const cb=cad?Object.entries(cad.brands).map(([k,c])=>{const [s,b]=k.split('|');const exp=c.learned?('typically back after \~'+c.median_gap_days+' days (learned)'):c.prior?('prior: '+c.prior.lo+(c.prior.hi?'-'+c.prior.hi:'+')+' days'):'not enough data');return [esc(s),esc(b),c.days_seen+' days seen',c.gaps.length+' gaps',c.days_since_seen+' days ago',esc(exp)]}):[];
&#x20;rows(document.getElementById('cad'),['Store','Brand','Seen','Gaps','Last seen','Expected return'],cb);
&#x20;const db=[];if(dp)for(const [s,l] of Object.entries(dp.stores))for(const d of l)if(d.recurring){const w=['Su','Mo','Tu','We','Th','Fr','Sa'].map((n,i)=>d.weekdays[i]?n+' x'+d.weekdays[i]:'').filter(Boolean).join(', ');db.push([esc(s),esc(d.title),d.days_seen+' days',esc(w),d.items_last+' items'])}
&#x20;rows(document.getElementById('deal'),['Store','Deal title','Seen','Weekdays','Items last'],db);
})();
\</script>\</body>\</html>
